cd <scratch> && cat > h2t.py <<'EOF'
import sys, re, html
from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(s):
        super().__init__(); s.out=[]; s.skip=0
    def handle_starttag(s,t,a):
        if t in('script','style','noscript'): s.skip+=1
        if t in('p','div','li','h1','h2','h3','h4','h5','br','tr','blockquote'): s.out.append('\n')
        if t=='li': s.out.append('- ')
        if t in ('h2','h3','h4'): s.out.append('#'*int(t[1])+' ')
    def handle_endtag(s,t):
        if t in('script','style','noscript'): s.skip-=1
    def handle_data(s,d):
        if not s.skip: s.out.append(d)
for f in sys.argv[1:]:
    p=P(); p.feed(open(f,encoding='utf-8',errors='ignore').read())
    txt=''.join(p.out)
    txt=re.sub(r'[ \t]+',' ',txt); txt=re.sub(r'\n\s*\n+','\n',txt)
    open(f.replace('.html','.txt'),'w').write(txt)
EOF
python3 h2t.py r*.html; wc -l r*.txt; grep -n "Patch 12.15\|PATCH HIGHLIGHTS\|Champions" r12.15.txt | head
